using UnityEngine;using UnityEditor;using System.Linq;
public static class InspectImport { public static string Main(){var path="Assets/Models/motorcycle-old/Optimized/Motoroller_Rigged.fbx";var imp=(ModelImporter)AssetImporter.GetAtPath(path);imp.bakeAxisConversion=true;imp.isReadable=true;imp.importCameras=false;imp.importLights=false;imp.SaveAndReimport();var go=AssetDatabase.LoadAssetAtPath<GameObject>(path);return string.Join("\n",go.GetComponentsInChildren<MeshFilter>().Select(m=>m.name+" pos="+m.transform.position+" scale="+m.transform.lossyScale+" rotation="+m.transform.eulerAngles+" bounds="+m.GetComponent<Renderer>().bounds));}}
